import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


@dataclass
class ValidationResult:
    valid: bool
    missing_required_fields: List[str]
    low_confidence_fields: List[Tuple[str, float]]
    extracted: Dict[str, Any]


def _get_field_value(field: Any) -> Any:
    if field is None:
        return None
    for attr in ("value", "content"):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return val
    return field


def _get_field_confidence(field: Any) -> Optional[float]:
    if field is None:
        return None
    confidence = getattr(field, "confidence", None)
    if confidence is None and isinstance(field, dict):
        confidence = field.get("confidence")
    return confidence


def _extract_invoice_fields(invoice_obj: Any) -> Dict[str, Dict[str, Any]]:
    fields = getattr(invoice_obj, "fields", None)
    if fields is None and isinstance(invoice_obj, dict):
        fields = invoice_obj.get("fields", {})
    if fields is None:
        fields = {}

    result = {}
    for key, field in fields.items():
        result[key] = {
            "value": _get_field_value(field),
            "confidence": _get_field_confidence(field),
        }
    return result


def validate_structured_document(
    document_bytes: bytes,
    required_fields: Optional[List[str]] = None,
    confidence_threshold: float = 0.8,
    model_id: str = "prebuilt-invoice",
) -> ValidationResult:
    """
    Uses Azure Document Intelligence prebuilt invoice to extract fields and validate:
      - required structured fields are present
      - extracted field confidences meet the provided threshold

    Environment variables:
      - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
      - AZURE_DOCUMENT_INTELLIGENCE_KEY
    """
    if required_fields is None:
        required_fields = [
            "InvoiceId",
            "InvoiceDate",
            "VendorName",
            "CustomerName",
            "DueDate",
            "InvoiceTotal",
        ]

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id=model_id,
        body=document_bytes,
        content_type="application/pdf",
    )
    result = poller.result()

    documents = getattr(result, "documents", None)
    if documents is None and isinstance(result, dict):
        documents = result.get("documents", [])

    if not documents:
        return ValidationResult(
            valid=False,
            missing_required_fields=required_fields[:],
            low_confidence_fields=[],
            extracted={},
        )

    invoice = documents[0]
    extracted = _extract_invoice_fields(invoice)

    missing_required_fields: List[str] = []
    low_confidence_fields: List[Tuple[str, float]] = []

    for field_name in required_fields:
        info = extracted.get(field_name)
        value = None if info is None else info.get("value")
        confidence = None if info is None else info.get("confidence")

        if value in (None, "", []):
            missing_required_fields.append(field_name)
        if confidence is None or confidence < confidence_threshold:
            low_confidence_fields.append((field_name, float(confidence or 0.0)))

    valid = not missing_required_fields and all(conf >= confidence_threshold for _, conf in low_confidence_fields)

    return ValidationResult(
        valid=valid,
        missing_required_fields=missing_required_fields,
        low_confidence_fields=low_confidence_fields,
        extracted=extracted,
    )
